    const LadbTabTutorials = function (element, options, dialog) {
        LadbAbstractTab.call(this, element, options, dialog);

        this.$btnSubmit = $('#ladb_btn_submit', this.$element);

        this.$page = $('.ladb-page', this.$element);

        this.tutorials = null;

    };
